<?php
function solveProblem($s) {
    $lowerCount = 0;
    $higherCount = 0;
    $len = strlen($s);
    for ($i = 0; $i < $len; $i++) {
        if (ctype_lower($s[$i])) {
            $lowerCount++;
        } else {
            $higherCount++;
        }

        if ($lowerCount > $len / 2) {
            return strtolower($s);
        }
    }
    return $lowerCount == $higherCount ? strtolower($s) : strtoupper($s);
}

$s = trim(fgets(STDIN));
echo solveProblem($s) . "\n";
?>
